create table if not exists public.chunks (
    id bigint generated by default as identity primary key,

    -- Stable identifier generated by our ingestion code.
    chunk_key text not null unique,

    -- Links each chunk to its source document and historical figure.
    document_id bigint not null
        references public.documents(id)
        on delete cascade,

    figure_id bigint not null
        references public.figures(id)
        on delete cascade,

    -- Position of the chunk within the document.
    chunk_index integer not null,

    -- Text used for retrieval and answer generation.
    content text not null,

    character_count integer not null,
    token_count integer not null,

    -- text-embedding-3-small produces 1,536 dimensions by default.
    embedding extensions.vector(1536),

    -- Optional flexible metadata for future fields such as headings.
    metadata jsonb not null default '{}'::jsonb,

    created_at timestamptz not null default now(),

    unique(document_id, chunk_index)
);

create index if not exists idx_chunks_document_id
    on public.chunks(document_id);

create index if not exists idx_chunks_figure_id
    on public.chunks(figure_id);

alter table public.chunks enable row level security;